import sys
from functools import lru_cache

s = sys.stdin.read().split()[0]
n = len(s)

@lru_cache(maxsize=None)
def ok(i, bal):
    if bal < 0:
        return False
    if i == n:
        return bal == 0
    ch = s[i]
    if ch == '(':
        return ok(i + 1, bal + 1)
    if ch == ')':
        return ok(i + 1, bal - 1)
    return ok(i + 1, bal + 1) or ok(i + 1, bal - 1) or ok(i + 1, bal)

print('true' if ok(0, 0) else 'false')

